# Legacy item replaced because its answer was debatable (correr → carrera)
DROP_LEGACY = {"escritura_l4_w05", "escritura_l1_w04"}


def build(b, legacy):
    for level in range(1, 6):
        for prompt, correct, wrong, expl in MC[level]:
            b.mc(M, level, prompt, correct, wrong, expl)
        for e in legacy:
            if e['level'] == level and e['id'] not in DROP_LEGACY:
                b.items[M].append(e)
        if level in WRITE_EXTRA:
            prompt, word, ans, hint, expl = WRITE_EXTRA[level]
            b.write(M, level, prompt, ans, hint, expl, word=word)
        for words in ORDER[level]:
            b.order(M, level, "Ordena las palabras para formar una frase", words, ' '.join(words))
